"""Metrics for agent evaluation."""

from dataclasses import dataclass
from typing import Any
from abc import ABC, abstractmethod
from .runner import RunResult, StepResult


@dataclass
class MetricResult:
    """Result of a metric computation."""
    name: str
    value: float
    details: dict[str, Any] = None

    def __post_init__(self):
        if self.details is None:
            self.details = {}


class Metric(ABC):
    """Abstract base class for metrics."""

    @property
    @abstractmethod
    def name(self) -> str:
        pass

    @abstractmethod
    def compute(self, run_result: RunResult) -> MetricResult:
        pass


class TaskCompletionRate(Metric):
    """Fraction of tasks completed successfully."""

    @property
    def name(self) -> str:
        return "task_completion_rate"

    def compute(self, run_result: RunResult) -> MetricResult:
        return MetricResult(
            name=self.name,
            value=1.0 if run_result.success else 0.0,
            details={"success": run_result.success}
        )


class StepSuccessRate(Metric):
    """Fraction of steps completed successfully."""

    @property
    def name(self) -> str:
        return "step_success_rate"

    def compute(self, run_result: RunResult) -> MetricResult:
        return MetricResult(
            name=self.name,
            value=run_result.step_success_rate,
            details={
                "total_steps": len(run_result.step_results),
                "successful_steps": sum(1 for s in run_result.step_results if s.success)
            }
        )


class ToolUsageEfficiency(Metric):
    """Ratio of successful tool calls to total tool calls."""

    @property
    def name(self) -> str:
        return "tool_usage_efficiency"

    def compute(self, run_result: RunResult) -> MetricResult:
        total_calls = 0
        successful_calls = 0

        for step in run_result.step_results:
            for call in step.tool_calls:
                total_calls += 1
                if call.get("success", True):  # Default to success if not specified
                    successful_calls += 1

        value = successful_calls / total_calls if total_calls > 0 else 1.0

        return MetricResult(
            name=self.name,
            value=value,
            details={
                "total_tool_calls": total_calls,
                "successful_tool_calls": successful_calls
            }
        )


class HallucinationRate(Metric):
    """Estimated rate of hallucinated content in outputs.

    This is a placeholder - real implementation would use
    fact-checking against ground truth or consistency checks.
    """

    @property
    def name(self) -> str:
        return "hallucination_rate"

    def compute(self, run_result: RunResult) -> MetricResult:
        # Placeholder: would need ground truth or consistency checking
        return MetricResult(
            name=self.name,
            value=0.0,
            details={"note": "Not implemented - requires ground truth or consistency checker"}
        )


class InstructionFollowingScore(Metric):
    """Score for how well the agent followed instructions.

    Placeholder - real implementation would use LLM-as-judge
    or structured output validation.
    """

    @property
    def name(self) -> str:
        return "instruction_following_score"

    def compute(self, run_result: RunResult) -> MetricResult:
        # Placeholder: would use LLM-as-judge or schema validation
        return MetricResult(
            name=self.name,
            value=1.0 if run_result.success else 0.5,
            details={"note": "Not implemented - requires LLM-as-judge or schema validation"}
        )


# Registry of available metrics
METRIC_REGISTRY = {
    "task_completion_rate": TaskCompletionRate,
    "step_success_rate": StepSuccessRate,
    "tool_usage_efficiency": ToolUsageEfficiency,
    "hallucination_rate": HallucinationRate,
    "instruction_following_score": InstructionFollowingScore,
}


def get_metric(name: str) -> Metric:
    """Get a metric instance by name."""
    if name not in METRIC_REGISTRY:
        raise ValueError(f"Unknown metric: {name}")
    return METRIC_REGISTRY[name]()


def compute_all_metrics(run_result: RunResult, metric_names: list[str]) -> dict[str, MetricResult]:
    """Compute all requested metrics for a run result."""
    results = {}
    for name in metric_names:
        metric = get_metric(name)
        results[name] = metric.compute(run_result)
    return results
